/* The legacy DOM initializes out of sight; reveal only the chosen finished view. */
(()=>{'use strict';let done=false;const fail=()=>{if(done)return;const text=document.getElementById('eldoriaBootMessage'),retry=document.getElementById('eldoriaBootRetry');if(text)text.textContent='Eldoria could not finish loading. Your saved progress is kept.';if(retry)retry.hidden=false};const finish=async()=>{if(done)return;await Promise.all([...document.querySelectorAll('link[rel="stylesheet"]')].filter(link=>!link.sheet).map(link=>new Promise(resolve=>{link.addEventListener('load',resolve,{once:true});link.addEventListener('error',resolve,{once:true});setTimeout(resolve,4000)})));if(document.getElementById('cityScene')){const start=performance.now();while(document.getElementById('cityScene').dataset.photoReady==='loading'&&performance.now()-start<6000)await new Promise(resolve=>setTimeout(resolve,40));window.ELDORIA_SCREEN_FIT?.fit()}await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));done=true;document.documentElement.classList.remove('eldoria-booting');document.getElementById('eldoriaBoot')?.remove()};window.EldoriaBoot={finish,fail};setTimeout(()=>{if(!done)fail()},20000)})();
